
(()=>{const tabs=[...document.querySelectorAll('.explore-tabs [role=tab]')];function activate(tab){tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!selected;});}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activate(tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();activate(tabs[n]);tabs[n].focus();}});});document.querySelectorAll('.explore-map-frame').forEach(frame=>{const svg=frame.querySelector('svg'),g=svg.querySelector('.map-geography');let scale=1,x=0,y=0,drag=null;function render(){g.setAttribute('transform',`translate(${450+x} ${310+y}) scale(${scale}) translate(-450 -310)`);}function zoom(factor){scale=Math.max(1,Math.min(6,scale*factor));if(scale===1){x=0;y=0;}render();}frame.querySelectorAll('[data-map-action]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.mapAction;if(a==='reset'){scale=1;x=0;y=0;render();}else zoom(a==='in'?1.35:1/1.35);}));frame.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||e.button!==0||e.target.closest('button,[role=button]'))return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};frame.setPointerCapture(e.pointerId);});frame.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const rect=svg.getBoundingClientRect(),unit=Math.max(900/rect.width,620/rect.height);x=Math.max(-900*scale,Math.min(900*scale,x+(e.clientX-drag.x)*unit));y=Math.max(-620*scale,Math.min(620*scale,y+(e.clientY-drag.y)*unit));drag.x=e.clientX;drag.y=e.clientY;render();});['pointerup','pointercancel','lostpointercapture'].forEach(type=>frame.addEventListener(type,()=>drag=null));frame.addEventListener('keydown',e=>{if(e.target!==frame)return;if(e.key==='+'||e.key==='='){e.preventDefault();zoom(1.35);}if(e.key==='-'){e.preventDefault();zoom(1/1.35);}if(e.key==='0'){scale=1;x=0;y=0;render();}});});})();
